    def findLatestStep(self, arr: List[int], m: int) -> int:
        n = len(arr)
        bits = bytearray(n + 2)
        ans = -1
        for step, p in enumerate(arr, 1):
            bits[p] = 1
            run = 0
            ok = False
            for i in range(1, n + 2):
                if bits[i]:
                    run += 1
                else:
                    if run == m:
                        ok = True
                    run = 0
            if ok:
                ans = step
        return ans

