        n = len(arr)
        parent = list(range(n + 1))
        size = [0] * (n + 1)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        cnt = [0] * (n + 1)
        ans = -1
        for step, p in enumerate(arr, 1):
            cur = 1
            for q in (p - 1, p + 1):
                if 1 <= q <= n and size[q] > 0:
                    r = find(q)
                    cnt[size[r]] -= 1
                    cur += size[r]
                    parent[r] = p
            size[p] = cur
            cnt[cur] += 1
