class Solution {
public:
    vector<int> parent, sz;
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    int findLatestStep(vector<int>& arr, int m) {
        int n = arr.size();
        parent.resize(n + 1);
        iota(parent.begin(), parent.end(), 0);
        sz.assign(n + 1, 0);
        vector<int> cnt(n + 1, 0);
        int ans = -1;
        for (int step = 1; step <= n; ++step) {
            int p = arr[step - 1];
            int cur = 1;
            for (int q : {p - 1, p + 1}) {
                if (q >= 1 && q <= n && sz[q] > 0) {
                    int r = find(q);
                    cnt[sz[r]]--;
                    cur += sz[r];
                    parent[r] = p;
                }
            }
            sz[p] = cur;
            cnt[cur]++;
            if (cnt[m] > 0) ans = step;
        }
        return ans;
    }
};

